# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "3.2.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v3.2.0/dedup-3.2.0-macos-arm64.tar.gz"
      sha256 "ab10dfd9f70446862d47a0a7f131e6b8f06a032a00e37eca2b3bd79d743fe2bb"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v3.2.0/dedup-3.2.0-macos-x86_64.tar.gz"
      sha256 "09a63a25afac7e0fad4a504b7dd8608ade7b3b3f286bbc7f320a3eb73dbe157e"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v3.2.0/dedup-3.2.0-linux-x86_64.tar.gz"
    sha256 "2c0dd78e61ba83cfdbd76f9d30f72b93d499505c82812c877545158d1e5ba53d"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
